class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column back to position
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[i][j] = number of ways to assign values to arr1[0...i] such that arr1[i] = j
        # We'll use dictionary to store only valid states

        # Initialize for first position
        dp = {}
        for j in range(nums[0] + 1):
            dp[(0, j)] = 1

        # Process each position from 1 to n-1
        for i in range(1, n):
            new_dp = {}
            # For each possible value of arr1[i]
            for val1 in range(nums[i] + 1):
                count = 0
                # For each possible value of arr1[i-1]
                for prev_val1 in range(nums[i-1] + 1):
                    # Check constraints:
                    # 1. arr1 is non-decreasing: val1 >= prev_val1
                    # 2. arr2 is non-increasing: (nums[i-1] - prev_val1) >= (nums[i] - val1)
                    #    which simplifies to: val1 - prev_val1 >= nums[i-1] - nums[i]
                    if val1 >= prev_val1 and val1 - prev_val1 >= nums[i-1] - nums[i]:
                        count = (count + dp.get((i-1, prev_val1), 0)) % MOD

                if count > 0:
                    new_dp[(i, val1)] = count

            dp = new_dp

        # Sum all valid configurations at the last position
        result = 0
        for val1 in range(nums[n-1] + 1):
            result = (result + dp.get((n-1, val1), 0)) % MOD

        return result

