class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Group picks by player
        player_picks = {}
        for player, color in pick:
            if player not in player_picks:
                player_picks[player] = []
            player_picks[player].append(color)

        # Count winning players
        winning_count = 0

        # Check each player from 0 to n-1
        for player in range(n):
            if player not in player_picks:
                # Player has no picks, so they can't win
                continue

            # Count frequency of each color picked by this player
            color_count = {}
            for color in player_picks[player]:
                color_count[color] = color_count.get(color, 0) + 1

            # Check if any color has at least (player + 1) balls
            # Player i needs at least (i+1) balls of the same color
            if max(color_count.values()) >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def count_row_flips():
            flips = 0
            for i in range(m):
                # For each row, compare positions j and (n-1-j)
                for j in range(n // 2):
                    # If values at symmetric positions are different, we need to flip one
                    if grid[i][j] != grid[i][n - 1 - j]:
                        flips += 1
            return flips

        def count_col_flips():
            flips = 0
            for j in range(n):
                # For each column, compare positions i and (m-1-i)
                for i in range(m // 2):
                    if grid[i][j] != grid[m - 1 - i][j]:
                        flips += 1
            return flips

        # Return minimum flips needed for rows or columns
        return min(count_row_flips(), count_col_flips())

